/**
 * OWON platform-level worker entry (generated by scripts/wrap-worker-entry.mjs
 * from this template at build time; do not edit dist/server/owon-entry.mjs).
 *
 * Runs for EVERY request before the Astro app (run_worker_first = /*), so it
 * covers prerendered asset pages too — those bypass Astro middleware (the
 * adapter serves them straight from ASSETS.fetch).
 *
 * 1. Canonical host/scheme: apex -> www, http -> https (301 GET/HEAD, 308 other).
 * 2. URL canonicalization (SEO):
 *    - directory routes force a single trailing slash  (/about  -> /about/)
 *    - file routes drop it                            (/contact/ -> /contact)
 *    - /index.html variants collapse to canonical      (/x/index.html -> /x/)
 *    - legacy aliases map to canonical URLs            (/contact-sales -> /contact)
 *    Fixes Google Coverage issues: with the adapter's 307 not firing in this
 *    deployment, every URL variant served 200 and Google indexed duplicate /
 *    alternate pages (60+ "alternate with canonical", 106 duplicate pairs).
 */
import main from './__ENTRY__';

/** Routes that canonically serve WITHOUT a trailing slash (file/SSR routes). */
const FILE_ROUTES = new Set(['/contact', '/privacy', '/terms']);

/** Legacy path aliases -> canonical URLs. */
const LEGACY_REDIRECTS = {
  '/contact-sales': '/contact',
  '/contact-sales/': '/contact',
  '/resources/case-studies': '/case-studies/',
  '/resources/case-studies/': '/case-studies/',
};

/** Returns the canonical pathname for `pathname`, or null when no redirect is needed. */
function canonicalPath(pathname) {
  // Legacy aliases first.
  if (Object.prototype.hasOwnProperty.call(LEGACY_REDIRECTS, pathname)) {
    return LEGACY_REDIRECTS[pathname];
  }

  // /x/index.html -> /x/ (or /x for file routes).
  const idx = pathname.indexOf('/index.html');
  if (idx !== -1) {
    const base = pathname.slice(0, idx);
    if (base === '') return '/';
    return FILE_ROUTES.has(base) ? base : base + '/';
  }

  // File routes: /contact/ -> /contact.
  for (const fr of FILE_ROUTES) {
    if (pathname === fr + '/') return fr;
  }

  // Never touch root, API routes, asset bundles, scripts, CMS or file-like paths.
  if (pathname === '/') return null;
  if (
    pathname.startsWith('/api/') ||
    pathname.startsWith('/_astro/') ||
    pathname.startsWith('/scripts/') ||
    pathname.startsWith('/keystatic') ||
    pathname.startsWith('/cdn-cgi/')
  ) {
    return null;
  }
  const last = pathname.split('/').pop() || '';
  if (last.includes('.')) return null;

  // Directory routes: force a single trailing slash (never on file routes).
  if (!pathname.endsWith('/') && !FILE_ROUTES.has(pathname)) return pathname + '/';
  return null;
}

export default {
  async fetch(request, env, context) {
    const url = new URL(request.url);
    const proto = (request.headers.get('x-forwarded-proto') ?? 'https').toLowerCase();

    // Canonical host + scheme.
    if (url.hostname === 'owon-iot.com' || proto === 'http') {
      const status = request.method === 'GET' || request.method === 'HEAD' ? 301 : 308;
      return Response.redirect('https://www.owon-iot.com' + url.pathname + url.search, status);
    }

    // Canonical URL (trailing slash / index.html / legacy aliases).
    if (url.hostname === 'www.owon-iot.com') {
      const target = canonicalPath(url.pathname);
      if (target) {
        const status = request.method === 'GET' || request.method === 'HEAD' ? 301 : 308;
        return Response.redirect('https://www.owon-iot.com' + target + url.search, status);
      }
    }

    return main.fetch(request, env, context);
  },
};
